import{d as h,C as n,o as g,c as m,a3 as i,E as s,j as t,a as u}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·卫灵公","description":"《论语》第 15 篇「卫灵公」——四十二章原文与导读。无为而治、杀身成仁、工欲善其事、躬自厚而薄责于人、君子求诸己、小不忍则乱大谋、有教无类。","frontmatter":{"title":"论语·卫灵公","description":"《论语》第 15 篇「卫灵公」——四十二章原文与导读。无为而治、杀身成仁、工欲善其事、躬自厚而薄责于人、君子求诸己、小不忍则乱大谋、有教无类。","category":"guide","aliases":["卫灵公","卫灵公篇","卫灵公第十五","论语卫灵公","lunyu 卫灵公"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-15.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-15.md","lastUpdated":1790316338000}'),d={name:"lizhimingde/sishu-wujing/lunyu/chapter-15.md"},w=h({...d,setup(y){const a=[{id:"yi",label:"一、俎豆之事，则尝闻之矣",showLabel:!0,sentences:[["卫灵公问",{text:"陈",glossary:"chen-zhen"},"于孔子，孔子对曰：“",{text:"俎豆",glossary:"zudou"},"之事，则尝闻之矣；军旅之事，未之学也。”明日遂行。"]],note:"卫灵公问陈（阵）于孔子。孔子对曰：「俎豆之事，则尝闻之矣；军旅之事，未之学也」——祭祀礼仪之事，我曾听说过；军旅之事，我没有学过。明日遂行。"},{id:"er",label:"二、君子固穷",showLabel:!0,sentences:[["在陈绝粮，从者病莫能兴。子路",{text:"愠见",glossary:"yunjian"},"曰：“君子亦有穷乎？”子曰：“君子",{text:"固穷",glossary:"guqiong"},"，小人穷斯",{text:"滥",glossary:"lan"},"矣。”"]],note:"在陈绝粮，从者病莫能兴。子路愠见曰：「君子亦有穷乎」——君子也有穷困之时吗？孔子说：「君子固穷，小人穷斯滥矣」——君子穷困时仍能固守（固＝固守），小人一穷便无所不为了。"},{id:"san",label:"三、予一以贯之",showLabel:!0,sentences:[["子曰：“赐也，女以予为多学而识之者与？”对曰：“然，非与？”曰：“非也，予一以贯之。”"]],note:"孔子说：「赐也，女（汝）以予为多学而识之者与」——赐啊，你以为我是多学而记得住的人吗？子贡对曰：「然，非与」——是的，难道不是吗？孔子说：「非也，予一以贯之」——不是；我是一以贯之的。（与《里仁》「吾道一以贯之」相呼应。）"},{id:"si",label:"四、知德者鲜矣",showLabel:!0,sentences:[["子曰：“由，知德者鲜矣。”"]],note:"「由，知德者鲜矣」——仲由，知德的人太少了。"},{id:"wu",label:"五、无为而治者其舜也与",showLabel:!0,sentences:[["子曰：“",{text:"无为而治",glossary:"wuweierzhi"},"者其舜也与！夫何为哉？恭己正南面而已矣。”"]],note:"「无为而治者其舜也与」——能无为而治者，大概只有舜吧！「夫何为哉？恭己正南面而已矣」——他做什么呢？只是庄严端正地朝南而坐罢了。"},{id:"liu",label:"六、言忠信，行笃敬",showLabel:!0,sentences:[["子张问行，子曰：“言忠信，行笃敬，虽",{text:"蛮貊",glossary:"manmo"},"之邦行矣；言不忠信，行不笃敬，虽",{text:"州里",glossary:"zhouli"},"行乎哉？立则见其参于前也；在舆则见其倚于衡也，夫然后行。”子张",{text:"书诸绅",glossary:"shuzhushen"},"。"]],note:"子张问「行」（如何使道行于外）。孔子说：「言忠信，行笃敬，虽蛮貊之邦行矣」——言语忠信、行为笃敬，纵然到蛮貊之邦也行得通；「言不忠信，行不笃敬，虽州里行乎哉」——言语不忠信、行为不笃敬，纵在本乡本土也行不通。「立则见其参于前也，在舆则见其倚于衡也，夫然后行」——站立时仿佛见「忠信笃敬」立于眼前，在车上仿佛见它倚于辕前横木，然后方能行。子张书诸绅（写在大带上）。"},{id:"qi",label:"七、直哉史鱼",showLabel:!0,sentences:[["子曰：“直哉",{text:"史鱼",glossary:"shiyu"},"！邦有道如矢，邦无道如矢。君子哉蘧伯玉！邦有道则仕，邦无道则可",{text:"卷而怀之",glossary:"juanerhuaizhi"},"。”"]],note:"「直哉史鱼！邦有道如矢，邦无道如矢」——史鱼真直啊！国有道时像箭一样直，国无道时也像箭一样直。「君子哉蘧伯玉！邦有道则仕，邦无道则可卷而怀之」——蘧伯玉真是君子啊！国有道便出仕，国无道便把本领卷而藏之。两人各见其高。"},{id:"ba",label:"八、知者不失人亦不失言",showLabel:!0,sentences:[["子曰：“可与言而不与之言，",{text:"失人",glossary:"shiren"},"；不可与言而与之言，",{text:"失言",glossary:"shiyan"},"。知者不失人亦不失言。”"]],note:"「可与言而不与之言，失人；不可与言而与之言，失言。知者不失人亦不失言」——可与言而不与之言，便失掉人；不可与言而与之言，便失掉言；智者既不失人，也不失言。"},{id:"jiu",label:"九、有杀身以成仁",showLabel:!0,sentences:[["子曰：“志士仁人无求生以害仁，有",{text:"杀身以成仁",glossary:"shashenchengren"},"。”"]],note:"「志士仁人无求生以害仁，有杀身以成仁」——志士仁人不为求生而害仁，只有牺牲生命以成仁。"},{id:"shi",label:"十、工欲善其事，必先利其器",showLabel:!0,sentences:[["子贡问为仁，子曰：“",{text:"工欲善其事，必先利其器",glossary:"gongyushanqishi"},"。居是邦也，事其大夫之贤者，友其士之仁者。”"]],note:"子贡问为仁。孔子说：「工欲善其事，必先利其器」——工匠欲做好其活，必先磨利其器。「居是邦也，事其大夫之贤者，友其士之仁者」——居于此国，便服事大夫中之贤者，结交士中之仁者。"},{id:"shiyi",label:"十一、行夏之时",showLabel:!0,sentences:[["颜渊问为邦，子曰：“行夏之时，乘殷之",{text:"辂",glossary:"lu-che"},"，服周之冕，乐则《韶》《舞》；放郑声，远佞人。郑声",{text:"淫",glossary:"yin-sheng"},"，佞人",{text:"殆",glossary:"dai-wei"},"。”"]],note:"颜渊问为邦。孔子说：「行夏之时」（用夏代之历），「乘殷之辂」（乘殷代的车），「服周之冕」（戴周代的礼帽），「乐则《韶》《舞》」；「放郑声，远佞人。郑声淫，佞人殆」——摒弃郑声，疏远佞人；郑声淫靡，佞人危险。"},{id:"shier",label:"十二、人无远虑，必有近忧",showLabel:!0,sentences:[["子曰：“人无远虑，必有近忧。”"]],note:"「人无远虑，必有近忧」——人无长远的考虑，必有眼前的忧患。"},{id:"shisan",label:"十三、吾未见好德如好色者也",showLabel:!0,sentences:[["子曰：“已矣乎！吾未见好德如好色者也。”"]],note:"「已矣乎！吾未见好德如好色者也」——算了吧！我没见过好德如好色那般真切的人。（与《子罕》第十八章略同，此加「已矣乎」，感更深。）"},{id:"shisi",label:"十四、臧文仲其窃位者与",showLabel:!0,sentences:[["子曰：“臧文仲其",{text:"窃位",glossary:"qiewei"},"者与！知柳下惠之贤而不与立也。”"]],note:"「臧文仲其窃位者与！知柳下惠之贤而不与立也」——臧文仲大概是个窃据官位者吧！他知柳下惠之贤，却不使他与自己同立于朝。"},{id:"shiwu",label:"十五、躬自厚而薄责于人",showLabel:!0,sentences:[["子曰：“",{text:"躬自厚而薄责于人",glossary:"gongzihou"},"，则远怨矣。”"]],note:"「躬自厚而薄责于人，则远怨矣」——厚责自己而薄责他人，便可远离怨恨。"},{id:"shiliu",label:"十六、不曰如之何者",showLabel:!0,sentences:[["子曰：“不曰‘如之何、如之何’者，吾末如之何也已矣。”"]],note:"「不曰『如之何、如之何』者，吾末如之何也已矣」——遇事不问「怎么办、怎么办」的人，我对他也无可如何了。"},{id:"shiqi",label:"十七、群居终日，言不及义",showLabel:!0,sentences:[["子曰：“群居终日，言不及义，好行",{text:"小慧",glossary:"xiaohui"},"，难矣哉！”"]],note:"「群居终日，言不及义，好行小慧，难矣哉」——终日群居，言不及义，好耍小聪明：这种人难有成就啊！"},{id:"shiba",label:"十八、君子义以为质",showLabel:!0,sentences:[["子曰：“君子",{text:"义以为质",glossary:"yiyiweizhi"},"，礼以行之，孙以出之，信以成之。君子哉！”"]],note:"「君子义以为质，礼以行之，孙（逊）以出之，信以成之。君子哉」——君子以义为本质，以礼行之，以谦逊出之，以诚信成之。真是君子啊！"},{id:"shijiu",label:"十九、君子病无能焉",showLabel:!0,sentences:[["子曰：“君子病无能焉，不病人之不己知也。”"]],note:"「君子病无能焉，不病人之不己知也」——君子患自己无能，不患别人不了解自己。"},{id:"ershi",label:"二十、君子疾没世而名不称焉",showLabel:!0,sentences:[["子曰：“君子疾",{text:"没世",glossary:"moshi2"},"而名不称焉。”"]],note:"「君子疾没世而名不称焉」——君子恨到死而名声不为人所称（一说「称」谓名实相称）。"},{id:"ershiyi",label:"二十一、君子求诸己",showLabel:!0,sentences:[["子曰：“君子求诸己，小人求诸人。”"]],note:"「君子求诸己，小人求诸人」——君子求之于己，小人求之于人。"},{id:"ershier",label:"二十二、君子矜而不争",showLabel:!0,sentences:[["子曰：“君子",{text:"矜而不争",glossary:"jin-erbuzheng"},"，群而不党。”"]],note:"「君子矜而不争，群而不党」——君子庄重而不争，合群而不结党。"},{id:"ershisan",label:"二十三、不以言举人，不以人废言",showLabel:!0,sentences:[["子曰：“君子不以言举人，不以人废言。”"]],note:"「君子不以言举人，不以人废言」——君子不因言辞而举荐人，也不因人而废弃其善言。"},{id:"ershisi",label:"二十四、其恕乎",showLabel:!0,sentences:[["子贡问曰：“有一言而可以终身行之者乎？”子曰：“其",{text:"恕",glossary:"shu-forgive"},"乎！己所不欲，勿施于人。”"]],note:"子贡问曰：「有一言而可以终身行之者乎」——有一个字可以终身奉行吗？孔子说：「其恕乎！己所不欲，勿施于人」——大概是「恕」吧！己所不欲，勿施于人。"},{id:"ershiwu",label:"二十五、谁毁谁誉",showLabel:!0,sentences:[["子曰：“吾之于人也，谁毁谁誉？如有所誉者，其有所",{text:"试",glossary:"shi-test"},"矣。斯民也，三代之所以",{text:"直道而行",glossary:"zhidaoerxing"},"也。”"]],note:"「吾之于人也，谁毁谁誉？如有所誉者，其有所试矣」——我于人，毁过谁？誉过谁？若有所誉，必是经过考验的。「斯民也，三代之所以直道而行也」——正是这些百姓，三代之所以能直道而行（即以此为据）。"},{id:"ershiliu",label:"二十六、吾犹及史之阙文也",showLabel:!0,sentences:[["子曰：“吾犹及史之",{text:"阙文",glossary:"quewen"},"也，有马者借人乘之，今亡矣夫！”"]],note:"「吾犹及史之阙文也」——我还赶得上见过史官存疑阙文（缺而不书）之风。「有马者借人乘之，今亡矣夫」——有马者借马与人乘（此句解说纷歧）；如今此风已没了。慨叹世风之降。"},{id:"ershiqi",label:"二十七、小不忍，则乱大谋",showLabel:!0,sentences:[["子曰：“巧言乱德，小不忍，则乱大谋。”"]],note:"「巧言乱德，小不忍，则乱大谋」——巧言乱德；小处不能忍，便乱大谋。"},{id:"ershiba",label:"二十八、众恶之，必察焉",showLabel:!0,sentences:[["子曰：“众恶之，必察焉；众好之，必察焉。”"]],note:"「众恶之，必察焉；众好之，必察焉」——众人所恶，必加考察；众人所好，亦必加考察。"},{id:"ershijiu",label:"二十九、人能弘道",showLabel:!0,sentences:[["子曰：“人能",{text:"弘道",glossary:"hongdao"},"，非道弘人。”"]],note:"「人能弘道，非道弘人」——人能弘大道，非道能弘大人。"},{id:"sanshi",label:"三十、过而不改，是谓过矣",showLabel:!0,sentences:[["子曰：“过而不改，是谓过矣。”"]],note:"「过而不改，是谓过矣」——有过而不改，这才叫做过。"},{id:"sanshiyi",label:"三十一、吾尝终日不食",showLabel:!0,sentences:[["子曰：“吾尝终日不食、终夜不寝以思，无益，不如学也。”"]],note:"「吾尝终日不食、终夜不寝以思，无益，不如学也」——我曾终日不食、终夜不寝地思索，无益；不如学习。"},{id:"sanshier",label:"三十二、君子忧道不忧贫",showLabel:!0,sentences:[["子曰：“君子谋道不谋食。耕也",{text:"馁",glossary:"nei"},"在其中矣，学也禄在其中矣。君子忧道不忧贫。”"]],note:"「君子谋道不谋食」——君子谋道不谋食。「耕也馁在其中矣，学也禄在其中矣」——耕田，饥馁在其中；为学，俸禄在其中。「君子忧道不忧贫」——君子忧道，不忧贫。"},{id:"sanshisan",label:"三十三、知及之，仁不能守之",showLabel:!0,sentences:[["子曰：“知及之，仁不能守之，虽得之，必失之；知及之，仁能守之，不庄以",{text:"莅",glossary:"li-lin"},"之，则民不敬；知及之，仁能守之，庄以莅之，动之不以礼，未善也。”"]],note:"「知及之，仁不能守之，虽得之，必失之」——智足以得之，仁不能守之，虽得必失。「知及之，仁能守之，不庄以莅之，则民不敬」——智得仁守，而不以庄重临民，则民不敬。「知及之，仁能守之，庄以莅之，动之不以礼，未善也」——三者皆备，而动不以礼，亦未尽善。四层递进。"},{id:"sanshisi",label:"三十四、君子不可小知而可大受也",showLabel:!0,sentences:[["子曰：“君子不可",{text:"小知",glossary:"xiaozhi"},"而可大受也，小人不可大受而可小知也。”"]],note:"「君子不可小知而可大受也，小人不可大受而可小知也」——君子不可以小处测知（小处未必看得准），却可承受大任；小人不可承受大任，却可于小处测知。"},{id:"sanshiwu",label:"三十五、民之于仁也，甚于水火",showLabel:!0,sentences:[["子曰：“民之于仁也，甚于水火。水火，吾见",{text:"蹈",glossary:"dao-ta"},"而死者矣，未见蹈仁而死者也。”"]],note:"「民之于仁也，甚于水火」——民之需要仁，甚于水火。「水火，吾见蹈而死者矣，未见蹈仁而死者也」——水火，吾见有人蹈之而死；未见有人蹈仁而死。"},{id:"sanshiliu",label:"三十六、当仁不让于师",showLabel:!0,sentences:[["子曰：“当仁不让于师。”"]],note:"「当仁不让于师」——面对当行仁之事，即对老师也不必谦让。"},{id:"sanshiqi",label:"三十七、君子贞而不谅",showLabel:!0,sentences:[["子曰：“君子",{text:"贞而不谅",glossary:"zhenerbuliang"},"。”"]],note:"「君子贞而不谅」——君子守大节（贞＝正而固），而不拘守小信（谅＝小信）。"},{id:"sanshiba",label:"三十八、敬其事而后其食",showLabel:!0,sentences:[["子曰：“事君，敬其事而后其食。”"]],note:"「事君，敬其事而后其食」——事君，先敬其事而后食其禄。"},{id:"sanshijiu",label:"三十九、有教无类",showLabel:!0,sentences:[["子曰：“有教无类。”"]],note:"「有教无类」——施教不分（贵贱、地域之）类。"},{id:"sishi",label:"四十、道不同，不相为谋",showLabel:!0,sentences:[["子曰：“道不同，不相为谋。”"]],note:"「道不同，不相为谋」——道不同者，不与之相谋。"},{id:"sishiyi",label:"四十一、辞达而已矣",showLabel:!0,sentences:[["子曰：“辞达而已矣。”"]],note:"「辞达而已矣」——言辞，达意而已（不必过事修饰）。"},{id:"sishier",label:"四十二、固相师之道也",showLabel:!0,sentences:[["师冕见，及阶，子曰：“阶也。”及席，子曰：“席也。”皆坐，子告之曰：“某在斯，某在斯。”师冕出。子张问曰：“与师言之道与？”子曰：“然，固",{text:"相师之道",glossary:"xiangshizhidao"},"也。”"]],note:"师冕（盲乐师）见。及阶，孔子说「阶也」；及席，说「席也」。皆坐，孔子告之曰「某在斯，某在斯」。师冕出，子张问曰：「与师言之道与」——这是与乐师言说之道吗？孔子说：「然，固相师之道也」——是；这本来就是相助乐师之道（相＝助）。"}],r=[{id:"chen-zhen",term:"陈",pinyin:"zhèn",meaning:"同「阵」，军旅列阵之事。卫灵公问陈，孔子答「军旅之事未之学也」，遂行——不合则去。"},{id:"zudou",term:"俎豆",pinyin:"zǔ dòu",meaning:"古代祭祀用的礼器，代指礼仪之事。"},{id:"yunjian",term:"愠见",pinyin:"yùn jiàn",meaning:"带着不满的神色来见。见：同「现」。"},{id:"guqiong",term:"固穷",pinyin:"gù qióng",meaning:"固守穷困（处穷而不失其守）。"},{id:"lan",term:"滥",pinyin:"làn",meaning:"泛滥、无所不至。小人穷斯滥矣：小人一旦穷困就什么事都做得出来。"},{id:"wuweierzhi",term:"无为而治",pinyin:"wú wéi ér zhì",meaning:"不妄为而天下自治。此处的「无为」指任贤得人、己不烦扰，非什么都不做。"},{id:"manmo",term:"蛮貊",pinyin:"mán mò",meaning:"南蛮北貊，泛指文化未开之地。"},{id:"zhouli",term:"州里",pinyin:"zhōu lǐ",meaning:"本乡本土（二十五家为里，二千五百家为州）。"},{id:"shuzhushen",term:"书诸绅",pinyin:"shū zhū shēn",meaning:"写在衣带上。绅：束腰的大带。子张把这话写下来随身记着。"},{id:"shiyu",term:"史鱼",pinyin:"shǐ yú",meaning:"卫国大夫史鰌，以直谏闻名（临终嘱以尸谏）。"},{id:"juanerhuaizhi",term:"卷而怀之",pinyin:"juǎn ér huái zhī",meaning:"把本领收起来藏好，指隐退不仕。"},{id:"shiren",term:"失人",pinyin:"shī rén",meaning:"错过值得交谈的人。"},{id:"shiyan",term:"失言",pinyin:"shī yán",meaning:"说错了话（对不该说的人说了）。"},{id:"shashenchengren",term:"杀身以成仁",pinyin:"shā shēn yǐ chéng rén",meaning:"牺牲生命来成全仁。这是儒家生死观最著名的表述之一。"},{id:"gongyushanqishi",term:"工欲善其事，必先利其器",pinyin:"gōng yù shàn qí shì， bì xiān lì qí qì",meaning:"工匠要做好活，先得把工具磨快。喻做事先备其条件。"},{id:"lu-che",term:"辂",pinyin:"lù",meaning:"大车（此指殷代的车，形制质朴）。"},{id:"yin-sheng",term:"淫",pinyin:"yín",meaning:"过度、放纵。郑声淫：郑国的音乐放纵过甚。"},{id:"dai-wei",term:"殆",pinyin:"dài",meaning:"危险。佞人殆：花言巧语的人危险。"},{id:"qiewei",term:"窃位",pinyin:"qiè wèi",meaning:"窃据官位（在位而不称职、不荐贤）。"},{id:"gongzihou",term:"躬自厚而薄责于人",pinyin:"gōng zì hòu ér bó zé yú rén",meaning:"多责备自己，少责备别人。躬：自身。"},{id:"xiaohui",term:"小慧",pinyin:"xiǎo huì",meaning:"小聪明。"},{id:"yiyiweizhi",term:"义以为质",pinyin:"yì yǐ wéi zhì",meaning:"以义为根本（质：本）。礼以行之、孙以出之、信以成之——义为本，礼、逊、信为用。"},{id:"moshi2",term:"没世",pinyin:"mò shì",meaning:"终身、到死。疾没世而名不称焉：以终身而名声不称其德为忧。"},{id:"jin-erbuzheng",term:"矜而不争",pinyin:"jīn ér bù zhēng",meaning:"矜：自重、庄敬。君子自重而不与人争。"},{id:"shu-forgive",term:"恕",pinyin:"shù",meaning:"推己及人（己所不欲，勿施于人）。子贡问「一言可终身行之」，孔子答以「恕」。"},{id:"shi-test",term:"试",pinyin:"shì",meaning:"考察、实践检验。其有所试矣：所称赞的人是经过考察的。"},{id:"zhidaoerxing",term:"直道而行",pinyin:"zhí dào ér xíng",meaning:"依正道而行。"},{id:"quewen",term:"阙文",pinyin:"quē wén",meaning:"空缺存疑的文字（史官记史，遇疑则缺，不妄补）。"},{id:"hongdao",term:"弘道",pinyin:"hóng dào",meaning:"把道发扬光大。人能弘道：道要靠人来发扬，不是道来抬高人。"},{id:"nei",term:"馁",pinyin:"něi",meaning:"饥饿。耕也馁在其中矣：种田也可能挨饿。"},{id:"li-lin",term:"莅",pinyin:"lì",meaning:"临、到（指临民治事）。"},{id:"xiaozhi",term:"小知",pinyin:"xiǎo zhī",meaning:"从小处赏识、任以小职。可大受：可以承担大任。"},{id:"dao-ta",term:"蹈",pinyin:"dǎo",meaning:"踩、踏入。蹈水火：踩进水里火里。"},{id:"zhenerbuliang",term:"贞而不谅",pinyin:"zhēn ér bù liàng",meaning:"守正而不拘于小信。贞：正而固；谅：小信。"},{id:"xiangshizhidao",term:"相师之道",pinyin:"xiàng shī zhī dào",meaning:"帮助盲乐师（师冕）的礼数。相：辅佐、引导。"}];return(p,e)=>{const l=n("DaoTextReading"),o=n("DaoKeywordCards");return g(),m("div",null,[e[0]||(e[0]=i('<h1 id="论语·卫灵公" tabindex="-1">论语·卫灵公 <a class="header-anchor" href="#论语·卫灵公" aria-label="Permalink to &quot;论语·卫灵公&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《卫灵公》四十二章，是**《论语》里格言密度最高的一篇**。开局两章先立人：「军旅之事，未之学也」——话不投机，第二天就走；「君子固穷，小人穷斯滥矣」——陈蔡绝粮时的回答。</p><p>往后几乎是格言的连缀：<strong>无为而治、言忠信行笃敬、可与言而不与之言、杀身以成仁、工欲善其事必先利其器、人无远虑必有近忧、躬自厚而薄责于人、君子求诸己、不以言举人、其恕乎、人能弘道、过而不改是谓过矣、有教无类、道不同不相为谋、辞达而已矣</strong>。</p><p>这一篇的末章写得好：师冕是盲乐师，孔子一路提示他哪儿是台阶、哪儿是席位，坐下后告诉他「某在斯，某在斯」。子张问这是不是与盲者说话的方式，孔子说：<strong>「然，固相师之道也。」</strong> 全篇的格言收在一个极小的动作上。</p><p>默认竹简沉浸通读；切「经典阅读」可点生词。</p>',6)),s(l,{colophon:"卫灵公第十五 · 四十二章",tone:"ink",sections:a,glossary:r,"default-mode":"slips","aria-label":"论语·卫灵公 原文"}),e[1]||(e[1]=t("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[u("【原典层】注音与字词 "),t("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),s(o,{items:[{term:"陈",pinyin:["zhèn"],meaning:"同「阵」，军旅列阵之事。卫灵公问陈，孔子答「军旅之事未之学也」，遂行——不合则去。"},{term:"俎豆",pinyin:["zǔ","dòu"],meaning:"古代祭祀用的礼器，代指礼仪之事。"},{term:"愠见",pinyin:["yùn","jiàn"],meaning:"带着不满的神色来见。见：同「现」。"},{term:"固穷",pinyin:["gù","qióng"],meaning:"固守穷困（处穷而不失其守）。"},{term:"滥",pinyin:["làn"],meaning:"泛滥、无所不至。小人穷斯滥矣：小人一旦穷困就什么事都做得出来。"},{term:"无为而治",pinyin:["wú","wéi","ér","zhì"],meaning:"不妄为而天下自治。此处的「无为」指任贤得人、己不烦扰，非什么都不做。"},{term:"蛮貊",pinyin:["mán","mò"],meaning:"南蛮北貊，泛指文化未开之地。"},{term:"州里",pinyin:["zhōu","lǐ"],meaning:"本乡本土（二十五家为里，二千五百家为州）。"},{term:"书诸绅",pinyin:["shū","zhū","shēn"],meaning:"写在衣带上。绅：束腰的大带。子张把这话写下来随身记着。"},{term:"史鱼",pinyin:["shǐ","yú"],meaning:"卫国大夫史鰌，以直谏闻名（临终嘱以尸谏）。"},{term:"卷而怀之",pinyin:["juǎn","ér","huái","zhī"],meaning:"把本领收起来藏好，指隐退不仕。"},{term:"失人",pinyin:["shī","rén"],meaning:"错过值得交谈的人。"},{term:"失言",pinyin:["shī","yán"],meaning:"说错了话（对不该说的人说了）。"},{term:"杀身以成仁",pinyin:["shā","shēn","yǐ","chéng","rén"],meaning:"牺牲生命来成全仁。这是儒家生死观最著名的表述之一。"},{term:"工欲善其事，必先利其器",pinyin:["gōng","yù","shàn","qí","shì，","bì","xiān","lì","qí","qì"],meaning:"工匠要做好活，先得把工具磨快。喻做事先备其条件。"},{term:"辂",pinyin:["lù"],meaning:"大车（此指殷代的车，形制质朴）。"},{term:"淫",pinyin:["yín"],meaning:"过度、放纵。郑声淫：郑国的音乐放纵过甚。"},{term:"殆",pinyin:["dài"],meaning:"危险。佞人殆：花言巧语的人危险。"},{term:"窃位",pinyin:["qiè","wèi"],meaning:"窃据官位（在位而不称职、不荐贤）。"},{term:"躬自厚而薄责于人",pinyin:["gōng","zì","hòu","ér","bó","zé","yú","rén"],meaning:"多责备自己，少责备别人。躬：自身。"},{term:"小慧",pinyin:["xiǎo","huì"],meaning:"小聪明。"},{term:"义以为质",pinyin:["yì","yǐ","wéi","zhì"],meaning:"以义为根本（质：本）。礼以行之、孙以出之、信以成之——义为本，礼、逊、信为用。"},{term:"没世",pinyin:["mò","shì"],meaning:"终身、到死。疾没世而名不称焉：以终身而名声不称其德为忧。"},{term:"矜而不争",pinyin:["jīn","ér","bù","zhēng"],meaning:"矜：自重、庄敬。君子自重而不与人争。"},{term:"恕",pinyin:["shù"],meaning:"推己及人（己所不欲，勿施于人）。子贡问「一言可终身行之」，孔子答以「恕」。"},{term:"试",pinyin:["shì"],meaning:"考察、实践检验。其有所试矣：所称赞的人是经过考察的。"},{term:"直道而行",pinyin:["zhí","dào","ér","xíng"],meaning:"依正道而行。"},{term:"阙文",pinyin:["quē","wén"],meaning:"空缺存疑的文字（史官记史，遇疑则缺，不妄补）。"},{term:"弘道",pinyin:["hóng","dào"],meaning:"把道发扬光大。人能弘道：道要靠人来发扬，不是道来抬高人。"},{term:"馁",pinyin:["něi"],meaning:"饥饿。耕也馁在其中矣：种田也可能挨饿。"},{term:"莅",pinyin:["lì"],meaning:"临、到（指临民治事）。"},{term:"小知",pinyin:["xiǎo","zhī"],meaning:"从小处赏识、任以小职。可大受：可以承担大任。"},{term:"蹈",pinyin:["dǎo"],meaning:"踩、踏入。蹈水火：踩进水里火里。"},{term:"贞而不谅",pinyin:["zhēn","ér","bù","liàng"],meaning:"守正而不拘于小信。贞：正而固；谅：小信。"},{term:"相师之道",pinyin:["xiàng","shī","zhī","dào"],meaning:"帮助盲乐师（师冕）的礼数。相：辅佐、引导。"}]}),e[2]||(e[2]=i('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《卫灵公》四十二章，几乎全是短章，像一部格言集。但归拢起来，有两组东西。</p><p><strong>一组是「守」</strong>：怎么在逆境里守住自己——「君子固穷，小人穷斯滥矣」「志士仁人无求生以害仁，有杀身以成仁」「曰：君子贞而不谅」「过而不改，是谓过矣」。</p><p><strong>一组是「求」</strong>：往哪儿用力——「君子求诸己，小人求诸人」「君子病无能焉，不病人之不己知也」「君子谋道不谋食」「人能弘道，非道弘人」「有教无类」。</p><p>中间还有孔子对「怎样办事」的几层提醒：言忠信行笃敬、工欲善其事必先利其器、躬自厚而薄责于人、不以言举人、众恶之必察焉、小不忍则乱大谋。<strong>末章落在为一个盲乐师引路这件小事上</strong>——格言之外，还有一个人的体贴。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它给出了「恕」这个字</strong>：子贡问「有一言可以终身行之者乎」，孔子答「其恕乎！己所不欲，勿施于人」——<strong>一个字管一辈子，这是孔子最凝练的一次回答。</strong></li><li><strong>它把「君子求诸己」讲成了分水岭</strong>：「君子求诸己，小人求诸人」——<strong>遇到问题的第一反应是向内还是向外</strong>，这一条几乎能分辨所有人。</li><li><strong>它对「评价他人」给出了极稳的方法</strong>：「众恶之，必察焉；众好之，必察焉」——<strong>多数人的意见要听，但不能照单全收</strong>；「不以言举人，不以人废言」——<strong>话和人要分开看</strong>。</li><li><strong>它有一句几乎被误读的名言</strong>：「以德报怨」在这里被明确纠正——孔子说「以直报怨，以德报德」（详见宪问篇）；而在这一篇，「躬自厚而薄责于人，则远怨矣」给了另一条路：<strong>把怨减掉，从少责备别人开始。</strong></li><li><strong>「有教无类」是教育史上极重的一句话</strong>：不分贵贱贤愚，只要来学就教。<strong>两千年后仍是教育公平的最早宣言。</strong></li><li><strong>它用末章示范了「道」的形态</strong>：全篇格言累累，最后收在为盲乐师报台阶、报座次上——<strong>道不在高处，在一个人对另一个人的照看上。</strong></li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用「恕」当一辈子的一条底线</strong>：做任何决定前问一句「如果换成我，愿意被这样对待吗」。</li><li><strong>用「君子求诸己」当遇事的第一动作</strong>：出了问题，先看自己能改什么，再看别人。</li><li><strong>用「众恶之必察，众好之必察」对付舆论</strong>：无论好话坏话，都要自己去核一遍。</li><li><strong>用「小不忍则乱大谋」按住冲动</strong>：一句气话、一次翻脸，往往毁掉长期积累的东西。</li><li><strong>学末章的体贴</strong>：<strong>知道对方的需要，并主动说出他看不见的东西</strong>——这是最朴素的「道」，也是最能照见修养的地方。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《卫灵公》这一篇，像一本小册子，一句一条。</p><p>「君子固穷，小人穷斯滥矣」——在陈国断粮、学生们都病倒的时候，子路抱怨，孔子就这样回答。「君子求诸己，小人求诸人」——出了问题，先看自己。「其恕乎！己所不欲，勿施于人」——一个字，可以用一辈子。「有教无类」「道不同不相为谋」「辞达而已矣」——几乎每一句都能单独立起来。</p><p>而这一篇的最后一章，写得很轻：一位盲乐师来见孔子。走到台阶前，孔子说这是台阶；走到座席前，孔子说这是座席；都坐下后，孔子告诉他谁在哪儿、谁在哪儿。</p><p>弟子问：跟盲人说话要这样吗？孔子说：是的，本来就是这样帮他的礼数。</p><p>四十二章的道理，最后落在这件小事上——<strong>所谓道，就是知道别人看不见什么，然后说给他听。</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「君子求诸己，小人求诸人」——我最近一次遇到麻烦时，第一反应是向内还是向外？</li><li>「其恕乎！己所不欲，勿施于人」——如果只能留一个字给自己当一生的准则，我会选哪个字？为什么？</li><li>「躬自厚而薄责于人，则远怨矣」——我对他人的责备和对自己的要求，比例是多少？</li><li>「众恶之，必察焉；众好之，必察焉」——我上一次跟着众人的评价下判断，是什么时候？事后证明对吗？</li><li>「不患人之不己知，患其不能也」——我有没有把「不被赏识」当成过不努力的借口？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-14">论语·宪问</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-16">论语·季氏</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',23))])}}});export{c as __pageData,w as default};
